/*
 * A021449  Decimal expansion of 1/445.
 * https://oeis.org/A021449
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = the n-th decimal digit of 1/445 (a(0) = first digit)
 * Range:     u8 n <= 4, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by long division: digit = floor(r*10 / 445);
   remainder r is updated as r = (r*10) % 445 starting from r = 1. */
/* This implementation caches computed digits so that a(n) can be
   called in any order and the cost remains O(max) with a small
   memory footprint. */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap  = 0;
    static uint16_t remainder = 1;   /* restart remainder at position 0 */

    /* Allocate initial cache */
    if (cache == NULL) {
        cache_cap = 64;                     /* arbitrary initial size */
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (cache == NULL) abort();
    }

    /* Expand cache if needed */
    if ((size_t)n >= cache_size) {
        /* Ensure capacity */
        if ((size_t)n >= cache_cap) {
            while (cache_cap <= (size_t)n) cache_cap <<= 1;
            seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            if (tmp == NULL) abort();
            cache = tmp;
        }

        /* Compute new terms via long division */
        for (size_t i = cache_size; i <= (size_t)n; ++i) {
            seq_t digit = (seq_t)remainder * 10 / 445;
            cache[i] = digit;
            remainder = ((uint16_t)remainder * 10) % 445;
        }
        cache_size = (size_t)n + 1;
    }

    return cache[n];
}
